mapper.select:
SELECT osch.outbound_schedule_id , osch.status , stat.name AS status_name , proc.product_code , proc.name AS product_name , wrhs.warehouse_code , wrhs.name AS warehouse_name , osch.schedule_qty , osch.schedule_date , COALESCE(ores.total_result_qty, 0) AS total_result_qty FROM outbound_schedules AS osch JOIN inventories AS invt ON osch.company_id = invt.company_id AND osch.inventory_id = invt.inventory_id JOIN products AS proc ON invt.company_id = proc.company_id AND invt.product_id = proc.product_id JOIN warehouses AS wrhs ON invt.company_id = wrhs.company_id AND invt.warehouse_id = wrhs.warehouse_id LEFT JOIN code_masters AS stat ON stat.code_type = 'OUTBOUND_STATUS' AND osch.status = stat.code LEFT JOIN ( SELECT outbound_schedule_id, SUM(result_qty) AS total_result_qty FROM outbound_results WHERE company_id = #{companyId} GROUP BY outbound_schedule_id ) AS ores ON osch.outbound_schedule_id = ores.outbound_schedule_id WHERE osch.company_id = #{companyId}
AND osch.status = #{status}
AND proc.product_code LIKE CONCAT('%', #{productCode}, '%')
AND proc.name LIKE CONCAT('%', #{productName}, '%')
AND wrhs.warehouse_code LIKE CONCAT('%', #{warehouseCode}, '%')
AND wrhs.name LIKE CONCAT('%', #{warehouseName}, '%')
ORDER BY osch.outbound_schedule_id;
